// Vereinheitlicht beide Trigger-Pfade auf ein gemeinsames Item mit
// DRY_RUN (Default false bei eigenstaendigem Zeitplan-Lauf).
// REQUIRE_CONFIRMATION kommt zentral aus trading.pipeline_config (siehe
// Node Kontext ergaenzen), nicht mehr als Konstante hier.
// Eingabe kommt seit Prioritaet 7/18 verschachtelt als {context, config, payload}.
const j = $json || {};
const ctx = j.context || {};
const cfg = j.config || {};
return [{ json: {
  run_id: ctx.run_id || ('standalone-' + Date.now()),
  _run_started_at: new Date().toISOString(),
  DRY_RUN: cfg.DRY_RUN === true || cfg.DRY_RUN === 'true'
} }];

// EMPFEHLUNGEN: STRATEGIE-ABGLEICH – Run Once for All Items
//
// Welle 2 (2026-08-01), AP4+AP5+AP7: kompletter Umbau von "News+Technik-Kombo"
// auf strategiesignal-getriebene Entscheidungen. Pro Ticker wird die
// dominante, regime-bereinigt staerkste unter allen passenden Strategien
// (mean_reversion/trend_following/breakout aus "02", news_event hier aus
// News+technischer Bestaetigung berechnet) gewaehlt. Andere passende
// Strategien werden als Alternativszenarien mitgespeichert. Opportunity/Risk/
// Evidence sind getrennte Dimensionen, KEINE Erfolgswahrscheinlichkeit.
// Welle 1s 12 harte Vetos, Risikomodell und Schliessungs-Fallback bleiben
// vollstaendig erhalten (siehe docs/HARTE_VETOS.md, docs/RISIKOMODELL_EINZELTRADE.md).
// DRY_RUN/REQUIRE_CONFIRMATION unveraendert.

function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
}
function round(v, d = 3) { if (v === null || v === undefined || isNaN(v)) return null; return parseFloat(Number(v).toFixed(d)); }

const heute = getBusinessDate();
const zeitstempel = new Date().toISOString();
const _triggerCtx = $('Kontext ergaenzen').all()[0];
const DRY_RUN = _triggerCtx && _triggerCtx.json ? _triggerCtx.json.DRY_RUN : false;
const REQUIRE_CONFIRMATION = _triggerCtx && _triggerCtx.json ? _triggerCtx.json.REQUIRE_CONFIRMATION : false;
const run_id = _triggerCtx && _triggerCtx.json ? _triggerCtx.json.run_id : null;
const TREND_KONFLIKT_SCHWELLE = _triggerCtx && _triggerCtx.json && !isNaN(Number(_triggerCtx.json.TREND_KONFLIKT_SCHWELLE)) ? Number(_triggerCtx.json.TREND_KONFLIKT_SCHWELLE) : 10;

const cfgNum = (key, fallback) => {
  const v = _triggerCtx && _triggerCtx.json ? _triggerCtx.json[key] : undefined;
  return v !== undefined && v !== null && !isNaN(Number(v)) ? Number(v) : fallback;
};
const RISK_CFG = {
  MODEL_PORTFOLIO_VALUE: cfgNum('MODEL_PORTFOLIO_VALUE', 100000),
  MAX_RISK_PER_TRADE_PCT: cfgNum('MAX_RISK_PER_TRADE_PCT', 1.0),
  MIN_REWARD_RISK_RATIO: cfgNum('MIN_REWARD_RISK_RATIO', 1.5),
  MAX_POSITION_VALUE_PCT: cfgNum('MAX_POSITION_VALUE_PCT', 20.0),
  DEFAULT_SLIPPAGE_BPS: cfgNum('DEFAULT_SLIPPAGE_BPS', 10),
  DEFAULT_FEES_BPS: cfgNum('DEFAULT_FEES_BPS', 15),
  MAX_DATA_AGE_MINUTES: cfgNum('MAX_DATA_AGE_MINUTES', 1440)
};
const RISK_MODEL_VERSION = 'welle1-v1';
const THESIS_RULE_VERSION = 'welle1-v1';
const REGIME_MATRIX_VERSION = 'regime-matrix-v1';

// ------------------------------------------------------------
// Datenquellen laden
// ------------------------------------------------------------
const techRows = $('DB: Technische Signale laden (Empf.)').all().map(i => i.json || {});
const newsRows = $('DB: News laden (Empf., trading.*)').all().map(i => i.json || {});
const empfehlungRows = $('DB: Bestehende Empfehlungen laden').all().map(i => i.json || {});
const trendRows = $input.all().map(i => i.json || {});
const strategyRows = $('DB: Strategiesignale laden (Empf.)').all().map(i => i.json || {});
const regimeRows = $('DB: Marktregime laden (Empf.)').all().map(i => i.json || {});
const matrixRows = $('DB: Regime-Matrix laden (Empf.)').all().map(i => i.json || {});
const fundHistRows = $('DB: Fundamental-Historie laden (Empf.)').all().map(i => i.json || {});
const regionRows = $('DB: Ticker-Region laden (Empf.)').all().map(i => i.json || {});

let marktkontextVerfuegbarHeute = true;
try {
  const mkRows = $('DB: Marktkontext heute (Empf.)').all();
  marktkontextVerfuegbarHeute = mkRows.length > 0 && !!(mkRows[0].json && mkRows[0].json.anzahl > 0);
} catch (e) {}

// Welle 1, Veto 9 (DB-Fehler) - Welle 2: auch leere Strategiesignal-/
// Regime-Tabellen sind ein starkes Indiz fuer einen fehlgeschlagenen
// vorgelagerten Lauf (02/02b), nicht fuer "heute zufaellig kein Signal".
const dbLesefehler = techRows.length === 0 || trendRows.length === 0 || strategyRows.length === 0;

// ------------------------------------------------------------
// Indizes aufbauen
// ------------------------------------------------------------
const trendByTicker = {};
for (const r of trendRows) {
  const k = String(r.ticker || '').trim();
  if (!k) continue;
  if (!trendByTicker[k]) trendByTicker[k] = [];
  trendByTicker[k].push(r);
}
for (const k of Object.keys(trendByTicker)) trendByTicker[k].sort((a, b) => String(a.snapshot_date).localeCompare(String(b.snapshot_date)));

const strategyByTicker = {};
for (const s of strategyRows) {
  const k = String(s.ticker || '').trim();
  if (!k) continue;
  if (!strategyByTicker[k]) strategyByTicker[k] = [];
  let evidence = [], blockers = [];
  try { evidence = typeof s.evidence_json === 'string' ? JSON.parse(s.evidence_json) : (s.evidence_json || []); } catch (e) {}
  try { blockers = typeof s.blockers_json === 'string' ? JSON.parse(s.blockers_json) : (s.blockers_json || []); } catch (e) {}
  strategyByTicker[k].push({ ...s, evidence, blockers });
}

const regimeByRegion = {};
for (const r of regimeRows) {
  let inputs = {};
  try { inputs = typeof r.inputs_json === 'string' ? JSON.parse(r.inputs_json) : (r.inputs_json || {}); } catch (e) {}
  regimeByRegion[r.region] = { ...r, inputs };
}

const matrixByKey = {};
for (const m of matrixRows) matrixByKey[m.strategy + '|' + m.combined_regime] = m;

const regionByTicker = {};
for (const r of regionRows) regionByTicker[String(r.ticker || '').trim()] = r.region;

// Welle 3, AP9: global deaktivierte Strategien (ueber einen aktivierten
// Lernvorschlag, siehe trading.strategy_status) werden als Kandidaten gar
// nicht erst zugelassen - deterministisch, kein automatisches Reaktivieren.
let strategyStatusRows = [];
try { strategyStatusRows = $('DB: Strategie-Status laden (Empf.)').all().map(i => i.json || {}); } catch (e) {}
const strategyAktivByName = {};
for (const s of strategyStatusRows) strategyAktivByName[s.strategy] = s.aktiv === true || s.aktiv === 'true';

const fundHistByTicker = {};
for (const f of fundHistRows) {
  const k = String(f.ticker || '').trim();
  if (!k) continue;
  if (!fundHistByTicker[k]) fundHistByTicker[k] = [];
  fundHistByTicker[k].push(f);
}
for (const k of Object.keys(fundHistByTicker)) fundHistByTicker[k].sort((a, b) => String(a.snapshot_date).localeCompare(String(b.snapshot_date)));

// Ticker->Sektor + heutige Signale (Basis-Kursdaten)
const tickerSektorMap = {};
const signalByTicker = {};
for (const s of techRows) {
  if (!s.ticker) continue;
  if (s.sektor) tickerSektorMap[String(s.ticker).trim()] = String(s.sektor).trim();
  if (String(s.datum || '').startsWith(heute)) {
    signalByTicker[String(s.ticker).trim()] = {
      ticker: String(s.ticker).trim(), name: s.name || '', sektor: s.sektor || '',
      aktueller_kurs: s.aktueller_kurs, handels_status: s.handels_status || '', richtung: s.richtung || ''
    };
  }
}

// ------------------------------------------------------------
// Helper: Trend/ATR/Datenqualitaet (Welle 1, unveraendert)
// ------------------------------------------------------------
function trendInfo(ticker) {
  const arr = trendByTicker[String(ticker || '').trim()] || [];
  if (arr.length < 2) return { richtung: 'unbekannt', punkte: arr.length, delta: 0 };
  const erstRsi = Number(arr[0].rsi);
  const letztRsi = Number(arr[arr.length - 1].rsi);
  if (isNaN(erstRsi) || isNaN(letztRsi)) return { richtung: 'unbekannt', punkte: arr.length, delta: 0 };
  const delta = letztRsi - erstRsi;
  let richtung = 'seitwaerts';
  if (delta > 1) richtung = 'steigend'; else if (delta < -1) richtung = 'fallend';
  return { richtung, punkte: arr.length, delta };
}
function atrInfo(ticker) {
  const arr = trendByTicker[String(ticker || '').trim()] || [];
  if (arr.length === 0) return { verfuegbar: false, atr: null, stop: null, target: null };
  const letzter = arr[arr.length - 1];
  const atr = Number(letzter.atr_14_numeric);
  if (letzter.atr_14_numeric == null || isNaN(atr) || atr <= 0) return { verfuegbar: false, atr: null, stop: null, target: null };
  const stop = letzter.atr_stop_numeric != null ? Number(letzter.atr_stop_numeric) : null;
  const target = letzter.atr_target_numeric != null ? Number(letzter.atr_target_numeric) : null;
  return { verfuegbar: true, atr, stop, target };
}
function qualityInfo(ticker) {
  const arr = trendByTicker[String(ticker || '').trim()] || [];
  if (arr.length === 0) return { dataQualityStatus: 'unknown', breakoutHistoryAusreichend: null, dominantStrategy: null, sessionStatus: 'unknown' };
  const letzter = arr[arr.length - 1];
  return {
    dataQualityStatus: letzter.data_quality_status || 'unknown',
    breakoutHistoryAusreichend: letzter.breakout_history_ausreichend === true || letzter.breakout_history_ausreichend === 'true',
    dominantStrategy: letzter.dominant_strategy || null,
    sessionStatus: letzter.session_status || 'unknown'
  };
}
function letzterGueltigerKurs(ticker) {
  const arr = trendByTicker[String(ticker || '').trim()] || [];
  for (let i = arr.length - 1; i >= 0; i--) {
    const v = Number(arr[i].aktueller_kurs);
    if (!isNaN(v) && v > 0) return { kurs: v, datum: arr[i].snapshot_date };
  }
  return null;
}
function veto(code, source, message, observed, required) {
  return { code, severity: 'hard', source, message, observed_value: observed, required_value: required };
}

// ------------------------------------------------------------
// Welle 2, AP5: Fundamentaltrend aus Point-in-Time-Historie (Welle 1, Phase 5).
// Umsatz-/Gewinntrend (absolut) sind in der Quelle NICHT vorhanden - bleiben
// explizit 'not_available', werden NICHT durch die KI ergaenzt.
// ------------------------------------------------------------
function fundamentalTrend(ticker) {
  const rows = fundHistByTicker[String(ticker || '').trim()] || [];
  if (rows.length < 2) {
    return {
      quality: { roe_trend_pct: null, margin_trend_pct: null, revenue_trend: 'not_available', earnings_trend: 'not_available', data_quality: 'invalid' },
      momentum: { direction: 'unbekannt', debt_trend_pct: null, revisions_verglichen: rows.length },
      valuation: { kgv_trend_pct: null, kbv_trend_pct: null, analyst_target_trend_pct: null },
      dataQuality: 'invalid'
    };
  }
  const first = rows[0], last = rows[rows.length - 1];
  function delta(field) {
    const a = Number(first[field]), b = Number(last[field]);
    if (isNaN(a) || isNaN(b) || a === 0) return null;
    return round(((b - a) / Math.abs(a)) * 100, 2);
  }
  const roeTrend = delta('eigenkapitalrendite_numeric');
  const margeTrend = delta('gewinnmarge_numeric');
  const verschuldungTrend = delta('verschuldungsgrad_numeric');
  const zielTrend = delta('kursziel_numeric');
  const kgvTrend = delta('kgv_numeric');
  const kbvTrend = delta('kbv_numeric');
  const dataQuality = rows.length >= 5 ? 'valid' : 'limited';
  let direction = 'unbekannt';
  if (roeTrend !== null && margeTrend !== null) direction = (roeTrend + margeTrend) > 0 ? 'positiv' : 'negativ';
  else if (roeTrend !== null) direction = roeTrend > 0 ? 'positiv' : 'negativ';
  else if (margeTrend !== null) direction = margeTrend > 0 ? 'positiv' : 'negativ';
  return {
    quality: { roe_trend_pct: roeTrend, margin_trend_pct: margeTrend, revenue_trend: 'not_available', earnings_trend: 'not_available', data_quality: dataQuality },
    momentum: { direction, debt_trend_pct: verschuldungTrend, revisions_verglichen: rows.length },
    valuation: { kgv_trend_pct: kgvTrend, kbv_trend_pct: kbvTrend, analyst_target_trend_pct: zielTrend },
    dataQuality
  };
}

// ------------------------------------------------------------
// Welle 2, AP4: Evidenzgruppen (Doppelzaehlung korrelierter Indikatoren
// vermeiden - dokumentiert in docs/OPPORTUNITY_RISK_EVIDENCE.md).
// ------------------------------------------------------------
function classifyEvidenceGroup(text) {
  const t = String(text || '').toLowerCase();
  if (t.includes('rsi') || t.includes('bollinger')) return 'overextension';
  if (t.includes('macd')) return 'momentum';
  if (t.includes('ema20') || t.includes('ema200') || t.includes('trend')) return 'trend_confirmation';
  if (t.includes('volumen')) return 'volume';
  if (t.includes('bewegung') || t.includes('52-wochen') || t.includes('ausbruch')) return 'price_move';
  return 'other';
}
function evidenceConfidence(dominant, fundTrend, hatNews) {
  const groups = new Set();
  for (const e of (dominant.evidence || [])) groups.add(classifyEvidenceGroup(e));
  if (fundTrend.quality.data_quality !== 'invalid') groups.add('fundamental');
  if (hatNews) groups.add('news');
  const TOTAL_MOEGLICHE_GRUPPEN = 6; // overextension, momentum, trend_confirmation, volume, price_move, fundamental/news
  let conf = groups.size / TOTAL_MOEGLICHE_GRUPPEN;
  const dq = Number(dominant.data_quality_score);
  conf *= !isNaN(dq) ? Math.max(0.3, dq) : 0.7;
  const fallzahl = fundTrend.momentum.revisions_verglichen || 0;
  if (fallzahl < 3) conf *= 0.8;
  return round(Math.min(1, conf), 3);
}

// ------------------------------------------------------------
// Welle 2, AP6: Einzeltrade-Risikomodell (Welle 1, unveraendert)
// ------------------------------------------------------------
function computeRisk(entry, stop, target) {
  const unitRisk = Math.abs(entry - stop);
  if (!(unitRisk > 0)) return null;
  const riskAmount = RISK_CFG.MODEL_PORTFOLIO_VALUE * (RISK_CFG.MAX_RISK_PER_TRADE_PCT / 100);
  const theoreticalQuantity = Math.floor(riskAmount / unitRisk);
  const positionValue = theoreticalQuantity * entry;
  const positionValuePct = RISK_CFG.MODEL_PORTFOLIO_VALUE > 0 ? (positionValue / RISK_CFG.MODEL_PORTFOLIO_VALUE) * 100 : null;
  const rewardRiskRatio = Math.abs(target - entry) / unitRisk;
  const estimatedFees = positionValue * (RISK_CFG.DEFAULT_FEES_BPS / 10000);
  const estimatedSlippage = positionValue * (RISK_CFG.DEFAULT_SLIPPAGE_BPS / 10000);
  const maxPlannedLoss = unitRisk * theoreticalQuantity + estimatedFees + estimatedSlippage;
  return {
    riskAmount: round(riskAmount, 2), unitRisk: round(unitRisk, 4), theoreticalQuantity,
    positionValue: round(positionValue, 2), positionValuePct: round(positionValuePct, 4),
    rewardRiskRatio: round(rewardRiskRatio, 4), estimatedFees: round(estimatedFees, 2),
    estimatedSlippage: round(estimatedSlippage, 2), maxPlannedLoss: round(maxPlannedLoss, 2)
  };
}
function computeThesis(strategy, ticker, richtung, evidenceText, horizonDaysOverride) {
  let s = strategy;
  let horizonDays = horizonDaysOverride;
  let invalidation;
  if (s === 'mean_reversion') { horizonDays = horizonDays || 3; invalidation = ['RSI kehrt in neutrale Zone (38-62) zurueck', 'Kurs verlaesst Bollinger-Band-Extrembereich']; }
  else if (s === 'trend_following') { horizonDays = horizonDays || 15; invalidation = ['MACD-Kreuzung gegen die Positionsrichtung', 'Kurs wechselt die Seite von EMA20']; }
  else if (s === 'breakout') { horizonDays = horizonDays || 7; invalidation = ['Kurs faellt/steigt zurueck unter/ueber das Ausbruchsniveau (Fehlausbruch)']; }
  else { s = 'news_event'; horizonDays = horizonDays || 2; invalidation = ['Gegenteilige starke Nachricht am selben oder Folgetag']; }
  const now = new Date();
  const createdAt = now.toISOString();
  const timeStopAt = new Date(now.getTime() + horizonDays * 86400000).toISOString();
  const thesis = (ticker + ' ' + (richtung === 'kauf' ? 'Long' : 'Short') + '-These (' + s + '): ' + evidenceText).slice(0, 480);
  return { strategy: s, tradeThesis: thesis, thesisCreatedAt: createdAt, timeStopAt, thesisExpiresAt: timeStopAt, expectedHorizonDays: horizonDays, invalidationConditions: invalidation, ruleVersion: THESIS_RULE_VERSION };
}

// ------------------------------------------------------------
// News/Event: Ticker-Zuordnung (aus Welle 1/Vor-Welle-1, unveraendert)
// ------------------------------------------------------------
const SEKTOR_KEYWORDS = {
  'Auto': ['auto', 'automobil', 'fahrzeug', 'e-auto', 'elektroauto', 'zulieferer', 'pkw'],
  'Energie': ['energie', 'strom', 'gas', 'öl', 'ölpreis', 'kraftwerk', 'erneuerbare'],
  'Chemie': ['chemie', 'chemiekonzern', 'chemieindustrie'],
  'Banken': ['bank', 'banken', 'zins', 'zinsen', 'ezb', 'kredit', 'finanzsektor'],
  'Pharma': ['pharma', 'medikament', 'arznei', 'biotech', 'arzneimittel'],
  'Telekom': ['telekom', 'mobilfunk', '5g', 'netzausbau', 'glasfaser'],
  'Versicherung': ['versicherung', 'versicherer'],
  'Technologie': ['software', 'chip', 'halbleiter', ' ki ', 'cloud', 'tech-branche'],
  'Industrie': ['industrie', 'maschinenbau', 'anlagenbau', 'industriekonzern'],
  'Sport': ['sportartikel', 'sportbekleidung'],
  'Konsumgüter': ['konsumgüter', 'konsumgüterkonzern'],
  'Gesundheit': ['gesundheitswesen', 'klinik', 'medizintechnik']
};
function sektorenAusText(text) {
  const t = String(text || '').toLowerCase();
  return Object.entries(SEKTOR_KEYWORDS).filter(([, kw]) => kw.some(k => t.includes(k))).map(([sektor]) => sektor);
}
function tickerAusNews(n) {
  const genannt = Array.isArray(n.betroffene_ticker_json) ? n.betroffene_ticker_json : [];
  if (n.wirkungsebene !== 'sektor') return genannt;
  const matchText = [n.titel, n.wirkungs_begruendung, n.ticker_begruendung].filter(Boolean).join(' ');
  const sektoren = sektorenAusText(matchText);
  const sektorTicker = Object.entries(tickerSektorMap).filter(([, sektor]) => sektoren.includes(sektor)).map(([ticker]) => ticker);
  return Array.from(new Set([...genannt, ...sektorTicker]));
}

const newsRichtungByTicker = {};
const newsGrundByTicker = {};
const newsPublishedAtByTicker = {};
const widerspruechlich = new Set();
for (const n of newsRows) {
  if (n.wirkung_staerke !== 'hoch') continue;
  if (n.wirkungsrichtung !== 'positiv' && n.wirkungsrichtung !== 'negativ') continue;
  const ticker = tickerAusNews(n);
  for (const t of ticker) {
    if (!signalByTicker[t]) continue;
    const bisherige = newsRichtungByTicker[t];
    if (bisherige && bisherige !== n.wirkungsrichtung) {
      widerspruechlich.add(t);
      console.warn(`[Welle 1 Veto WIDERSPRUECHLICHE_NEWS] ${t}: widerspruechliche starke News am selben Tag.`);
      continue;
    }
    newsRichtungByTicker[t] = n.wirkungsrichtung;
    if (!newsGrundByTicker[t]) newsGrundByTicker[t] = [];
    newsGrundByTicker[t].push(String(n.titel || '').slice(0, 120));
    const pub = n.published_at ? new Date(n.published_at).getTime() : null;
    if (pub && (!newsPublishedAtByTicker[t] || pub > newsPublishedAtByTicker[t])) newsPublishedAtByTicker[t] = pub;
  }
}

// Welle 2, AP2: news_event als vierte, eigenstaendige Strategie - nur wenn
// eine aktuelle starke News vorliegt UND das technische Signal nicht
// widerspricht (Bestaetigung, keine Vermischung mit einem allgemeinen Score).
function newsEventSignalFor(ticker) {
  if (widerspruechlich.has(ticker)) return null;
  const newsRichtung = newsRichtungByTicker[ticker];
  if (!newsRichtung) return null;
  const signal = signalByTicker[ticker];
  if (!signal) return null;
  const kandidatenStatus = new Set(['handelskandidat', 'beobachten']);
  if (!kandidatenStatus.has(signal.handels_status)) return null;
  let direction = 'neutral';
  if (newsRichtung === 'positiv' && signal.richtung === 'long') direction = 'long';
  else if (newsRichtung === 'negativ' && signal.richtung === 'short') direction = 'short';
  if (direction === 'neutral') return null;
  const grund = (newsGrundByTicker[ticker] || []).join(' | ');
  return {
    strategy: 'news_event', direction, raw_score: 0.7, regime_fit: 0.7, data_quality_score: 0.8,
    evidence: ['Starke News: ' + grund, 'Technisches Signal bestaetigt (' + signal.richtung + '/' + signal.handels_status + ')'],
    blockers: [], expected_horizon_days: 2, entry_zone_low: null, entry_zone_high: null,
    stop_price: null, target_price: null, time_stop_at: null, rule_version: 'strategy-v1',
    grundText: grund
  };
}

// ------------------------------------------------------------
// Hebelprodukt-Hinweis - Welle 2, AP7: NICHT mehr Teil der allgemeinen
// Entscheidungslogik/Empfehlung, bleibt nur als bestehendes, deprecated
// Zusatzfeld (Rueckwaertskompatibilitaet, kein Migrationsplan fuer die
// Spalten selbst noetig - Berechnung bleibt unveraendert, nur die
// Praesentation/Betonung in Dashboard/Report aendert sich, siehe "07"/"10").
// ------------------------------------------------------------
const ONVISTA_SLUGS = {
  'SAP.DE': 'SAP', 'SIE.DE': 'Siemens', 'BASF.DE': 'BASF', 'ALV.DE': 'Allianz',
  'MBG.DE': 'Mercedes-Benz-Group-Daimler', 'BMW.DE': 'BMW', 'VOW3.DE': 'Volkswagen-VZ',
  'DBK.DE': 'Deutsche-Bank', 'DTE.DE': 'Deutsche-Telekom', 'RWE.DE': 'RWE',
  'BAYN.DE': 'Bayer', 'EOAN.DE': 'EON', 'ADS.DE': 'Adidas', 'HEN3.DE': 'Henkel', 'FRE.DE': 'Fresenius'
};
function hebelHinweis(ticker, aktuellerKurs, richtung) {
  const kurs = Number(aktuellerKurs);
  const slug = ONVISTA_SLUGS[ticker] || null;
  const link = slug ? `https://www.onvista.de/derivate/Knock-Outs/Knock-Outs-auf-${slug}` : '';
  if (isNaN(kurs) || kurs <= 0) return { typ: '', spanne: '', basis3: null, basis4: null, link, text: '' };
  const typ = richtung === 'kauf' ? 'Long Mini-Future' : 'Short Mini-Future';
  const basis3 = round(richtung === 'kauf' ? kurs * (1 - 1 / 3) : kurs * (1 + 1 / 3), 2);
  const basis4 = round(richtung === 'kauf' ? kurs * (1 - 1 / 4) : kurs * (1 + 1 / 4), 2);
  const text = `${typ}, Hebel 3-4x (nicht mehr). Rechnerischer Basispreis-Richtwert: ca. ${basis4} EUR (Hebel 4) bis ${basis3} EUR (Hebel 3). Kein konkretes Produkt - Emittent/Spread/Finanzierungskosten selbst pruefen. [Zusatzinfo, nicht Teil der Strategieentscheidung]`;
  return { typ, spanne: '3x-4x', basis3, basis4, link, text };
}

// ------------------------------------------------------------
// Welle 2, AP3+AP7: dominante Strategie je Ticker waehlen (regime-bereinigt)
// ------------------------------------------------------------
function evaluateTickerStrategies(ticker) {
  const signal = signalByTicker[ticker];
  if (!signal) return null;
  const region = regionByTicker[ticker] || 'Europa'; // Default-Fallback: aktuell alle Ticker XETRA/Europa (siehe docs/MARKTREGIME.md)
  const regime = regimeByRegion[region] || regimeByRegion['global'] || null;
  const combinedRegime = regime ? regime.combined_regime : 'unknown';

  const rawCandidates = [];
  for (const s of (strategyByTicker[ticker] || [])) {
    if (s.direction === 'neutral') continue;
    if (s.blockers && s.blockers.length > 0) continue; // z.B. HISTORY_252_MISSING aus "02"
    if (strategyAktivByName[s.strategy] === false) continue; // Welle 3, AP9: global deaktiviert
    rawCandidates.push({ ...s, entry_zone_low: s.entry_zone_low, entry_zone_high: s.entry_zone_high, stop_price: s.stop_price, target_price: s.target_price, expected_horizon_days: s.expected_horizon_days, time_stop_at: s.time_stop_at, evidence: s.evidence, data_quality_score: s.data_quality_score });
  }
  const ne = (strategyAktivByName['news_event'] !== false) ? newsEventSignalFor(ticker) : null;
  if (ne) rawCandidates.push(ne);

  const withFit = rawCandidates.map(c => {
    const m = matrixByKey[c.strategy + '|' + combinedRegime] || matrixByKey[c.strategy + '|unknown'];
    const fitMultiplier = m ? Number(m.fit_multiplier) : 0.3;
    const blocked = m ? m.blocked : false;
    return { ...c, combinedRegime, region, fitMultiplier, regimeBlocked: blocked, adjustedScore: round(Number(c.raw_score || 0) * fitMultiplier, 4) };
  });
  const blockedByRegime = withFit.filter(c => c.regimeBlocked);
  const usable = withFit.filter(c => !c.regimeBlocked && c.adjustedScore >= 0.15);
  usable.sort((a, b) => b.adjustedScore - a.adjustedScore);

  return { signal, region, regime, combinedRegime, dominant: usable[0] || null, alternatives: usable.slice(1), blockedByRegime, allCandidates: withFit };
}

// ------------------------------------------------------------
// Welle 1, AP5: zentrale Hart-Veto-Pruefung (Welle 2: nutzt jetzt das
// strategiespezifische Stop/Ziel aus dem Strategiesignal, faellt bei
// news_event ohne eigenes Stop/Ziel auf den bestehenden ATR-Wert zurueck).
// ------------------------------------------------------------
function pruefeOeffnungsVetos(ticker, dominant, signal) {
  const blockers = [];
  const kursWert = Number(signal.aktueller_kurs);
  const kursUngueltig = signal.aktueller_kurs === null || signal.aktueller_kurs === undefined || signal.aktueller_kurs === '' || isNaN(kursWert) || kursWert <= 0;
  if (kursUngueltig) blockers.push(veto('PRICE_MISSING', 'technical_signal', 'Kein gueltiger Referenzkurs vorhanden', signal.aktueller_kurs, '> 0'));

  const qi = qualityInfo(ticker);
  if (['invalid', 'stale', 'session_incomplete'].includes(qi.dataQualityStatus)) {
    blockers.push(veto('DATA_QUALITY', 'technical_signal', 'Datenqualitaet der Kurshistorie unzureichend fuer eine Eroeffnung', qi.dataQualityStatus, 'valid oder limited'));
  }

  const maxNewsAgeH = dominant.strategy === 'mean_reversion' ? 6 : dominant.strategy === 'breakout' ? 3 : dominant.strategy === 'trend_following' ? 24 : 12;
  const newsPub = newsPublishedAtByTicker[ticker];
  if (dominant.strategy === 'news_event' && newsPub) {
    const ageH = (Date.now() - newsPub) / 3600000;
    if (ageH > maxNewsAgeH) blockers.push(veto('NEWS_STALE', 'news', 'Ausloesende Nachricht ist fuer diese Strategie zu alt', Math.round(ageH * 10) / 10 + 'h', '<= ' + maxNewsAgeH + 'h'));
  }

  // Strategie-eigenes Stop/Ziel (aus trading.strategy_signals), bei news_event
  // (kein eigenes technisches Stopmodell) Fallback auf den bestehenden ATR-Wert.
  const atr = atrInfo(ticker);
  let stop = dominant.stop_price !== undefined && dominant.stop_price !== null ? Number(dominant.stop_price) : null;
  let target = dominant.target_price !== undefined && dominant.target_price !== null ? Number(dominant.target_price) : null;
  if ((stop === null || target === null) && dominant.strategy === 'news_event') { stop = atr.stop; target = atr.target; }
  if (stop === null || target === null || isNaN(stop) || isNaN(target)) {
    blockers.push(veto('STOP_TARGET_INVALID', dominant.strategy === 'news_event' ? 'technical_signal' : 'strategy_signal', 'Kein verwertbarer Stop/Ziel-Wert fuer die dominante Strategie', null, 'vorhanden'));
  }

  let stopWrongSide = false, targetWrongSide = false, risk = null;
  const richtung = dominant.direction === 'long' ? 'kauf' : 'verkauf';
  if (stop !== null && target !== null && !kursUngueltig) {
    if (richtung === 'kauf') {
      if (stop >= kursWert) { stopWrongSide = true; blockers.push(veto('STOP_WRONG_SIDE', 'risk_model', 'Stop liegt bei einem Long-Setup nicht unterhalb des Einstiegs', stop, '< ' + kursWert)); }
      if (target <= kursWert) { targetWrongSide = true; blockers.push(veto('TARGET_WRONG_SIDE', 'risk_model', 'Ziel liegt bei einem Long-Setup nicht oberhalb des Einstiegs', target, '> ' + kursWert)); }
    } else {
      if (stop <= kursWert) { stopWrongSide = true; blockers.push(veto('STOP_WRONG_SIDE', 'risk_model', 'Stop liegt bei einem Short-Setup nicht oberhalb des Einstiegs', stop, '> ' + kursWert)); }
      if (target >= kursWert) { targetWrongSide = true; blockers.push(veto('TARGET_WRONG_SIDE', 'risk_model', 'Ziel liegt bei einem Short-Setup nicht unterhalb des Einstiegs', target, '< ' + kursWert)); }
    }
    if (!stopWrongSide && !targetWrongSide) {
      risk = computeRisk(kursWert, stop, target);
      if (risk && risk.rewardRiskRatio < RISK_CFG.MIN_REWARD_RISK_RATIO) {
        blockers.push(veto('RRR_TOO_LOW', 'risk_model', 'Chance-Risiko-Verhaeltnis unterschreitet die konfigurierte Mindestgrenze', risk.rewardRiskRatio, '>= ' + RISK_CFG.MIN_REWARD_RISK_RATIO));
      }
    }
  }

  if (dbLesefehler) blockers.push(veto('DB_ERROR', 'pipeline', 'Ein vorgelagerter Datenbankzugriff lieferte unerwartet keine Zeilen', 'leer', '> 0 Zeilen'));
  if (!marktkontextVerfuegbarHeute) blockers.push(veto('REFERENZMARKT_FEHLT', 'market_context', 'Marktkontext-Referenzdaten (02b) liegen fuer heute nicht vor', 'keine Zeilen', '>= 1 Zeile'));
  if (widerspruechlich.has(ticker)) blockers.push(veto('WIDERSPRUECHLICHE_NEWS', 'news', 'Widerspruechliche starke News am selben Tag', 'positiv und negativ', 'eindeutig'));
  if (dominant.strategy === 'breakout' && qi.breakoutHistoryAusreichend === false) {
    blockers.push(veto('HISTORY_252_MISSING', 'technical_signal', 'Breakout-Signal ohne ausreichende 252-Tage-Historie', 'unzureichend', '>= 252 Handelstage oder Meta-52-Wochen-Wert'));
  }
  return { blockers, stop, target, risk };
}

// ------------------------------------------------------------
// Kandidat-Aufbau
// ------------------------------------------------------------
const output = [];
const newsEventSignalsToWrite = [];

function buildOpenCandidate(ticker, evalResult) {
  const { signal, region, regime, combinedRegime, dominant, alternatives, blockedByRegime } = evalResult;
  const richtung = dominant.direction === 'long' ? 'kauf' : 'verkauf';

  if (dominant.strategy === 'news_event') {
    newsEventSignalsToWrite.push({ ticker, business_date: heute, ...dominant });
  }

  const pruef = pruefeOeffnungsVetos(ticker, dominant, signal);
  if (pruef.blockers.length > 0) {
    console.warn(`[Welle 2] ${ticker}: Eroeffnung (${dominant.strategy}) hart vetoet (${pruef.blockers.map(b => b.code).join(', ')})`);
    output.push({ json: { _aktion: 'veto_log', run_id, ticker, veto_action: 'oeffnen', blockers: pruef.blockers, DRY_RUN } });
    return;
  }
  if (blockedByRegime.length > 0 && !dominant) {
    output.push({ json: { _aktion: 'veto_log', run_id, ticker, veto_action: 'oeffnen', blockers: [veto('REGIME_BLOCKED', 'market_regime', 'Alle passenden Strategien sind im aktuellen Marktregime blockiert', combinedRegime, 'nicht blockiert')], DRY_RUN } });
    return;
  }

  const kursWert = Number(signal.aktueller_kurs);
  const risk = pruef.risk || computeRisk(kursWert, pruef.stop, pruef.target);
  const softBlockers = [];
  if (risk && risk.positionValuePct !== null && risk.positionValuePct > RISK_CFG.MAX_POSITION_VALUE_PCT) {
    softBlockers.push({ code: 'POSITION_SIZE_HOCH', severity: 'soft', source: 'risk_model', message: 'Theoretische Positionsgroesse ueberschreitet MAX_POSITION_VALUE_PCT (informativ)', observed_value: risk.positionValuePct, required_value: '<= ' + RISK_CFG.MAX_POSITION_VALUE_PCT });
  }
  const trend = trendInfo(ticker);
  const trendKonflikt = (richtung === 'kauf' && trend.richtung === 'fallend') || (richtung === 'verkauf' && trend.richtung === 'steigend');
  const trendKonfliktStark = trendKonflikt && Math.abs(trend.delta) >= TREND_KONFLIKT_SCHWELLE;
  if (trendKonflikt) softBlockers.push({ code: 'TREND_KONFLIKT', severity: 'soft', source: 'trend', message: 'RSI-5-Tage-Trend widerspricht dem Tagessignal', observed_value: trend.richtung, required_value: 'gleichgerichtet oder unbekannt' });

  const fundTrend = fundamentalTrend(ticker);
  const hatNews = !!newsRichtungByTicker[ticker];
  const evidence = evidenceConfidence(dominant, fundTrend, hatNews);

  // Welle 2, AP4: Opportunity (Attraktivitaet, KEINE Erfolgswahrscheinlichkeit)
  let opportunity = 0;
  opportunity += 0.35 * Math.min(1, Number(dominant.raw_score) || 0);
  opportunity += 0.25 * Math.min(1, dominant.fitMultiplier || 0);
  const fundBonus = (fundTrend.momentum.direction === 'positiv' && richtung === 'kauf') || (fundTrend.momentum.direction === 'negativ' && richtung === 'verkauf') ? 0.15 : (fundTrend.momentum.direction === 'unbekannt' ? 0.05 : 0);
  opportunity += fundBonus;
  opportunity += 0.25 * (risk ? Math.min(1, risk.rewardRiskRatio / 3) : 0);
  opportunity = round(Math.min(1, opportunity), 3);

  // Risk (Gefaehrlichkeit, HOHER Wert = HOHES Risiko)
  let riskScore = 0;
  const stopDistPct = risk && kursWert ? Math.abs(risk.unitRisk / kursWert) : 0.05;
  riskScore += Math.min(0.3, stopDistPct * 3);
  riskScore += qi_dataQuality(ticker) === 'limited' ? 0.15 : (qi_dataQuality(ticker) === 'invalid' ? 0.3 : 0);
  riskScore += combinedRegime === 'stress' ? 0.3 : (combinedRegime === 'unknown' ? 0.1 : 0);
  riskScore += widerspruechlich.has(ticker) ? 0.15 : 0;
  riskScore = round(Math.min(1, riskScore), 3);

  const hh = hebelHinweis(ticker, signal.aktueller_kurs, richtung);
  const grundText = dominant.strategy === 'news_event' ? dominant.grundText : (dominant.evidence || []).join(' | ');
  const grund = `Strategie ${dominant.strategy} (${heute}), Regime ${combinedRegime}: ${grundText}`;
  const thesis = computeThesis(dominant.strategy, ticker, richtung, grundText, dominant.expected_horizon_days);

  if (!thesis.thesisExpiresAt || new Date(thesis.thesisExpiresAt).getTime() <= Date.now()) {
    output.push({ json: { _aktion: 'veto_log', run_id, ticker, veto_action: 'oeffnen', blockers: [veto('THESIS_INVALID', 'thesis_engine', 'Berechnete These/Zeitstop fehlt oder liegt bereits in der Vergangenheit', thesis.thesisExpiresAt, '> jetzt')], DRY_RUN } });
    return;
  }

  output.push({ json: {
    _aktion: 'oeffnen', _dry_run: DRY_RUN, _require_confirmation: REQUIRE_CONFIRMATION || trendKonfliktStark,
    _confirmation_reason: trendKonfliktStark ? ('Starker RSI-5-Tage-Gegentrend (' + trend.richtung + ', Δ' + trend.delta.toFixed(1) + ')') : (REQUIRE_CONFIRMATION ? 'REQUIRE_CONFIRMATION aktiv' : ''), run_id,
    ticker, name: signal.name, sektor: signal.sektor,
    richtung, entry_datum: heute, entry_kurs: signal.aktueller_kurs,
    entry_grund: '[SIMULATION - keine reale Order] ' + grund, letzte_aktualisierung: zeitstempel,
    hebelprodukt_typ: hh.typ, hebel_spanne: hh.spanne, basispreis_hebel_3: hh.basis3, basispreis_hebel_4: hh.basis4,
    onvista_link: hh.link, hebelprodukt_hinweis: hh.text,
    stop_price: pruef.stop, target_price: pruef.target,
    decision_score: Math.round(opportunity * 100),
    decision_blockers: softBlockers, market_regime: trend.richtung,
    is_theoretical: true,
    // Welle 2, AP4
    opportunity_score: opportunity, risk_score: riskScore, evidence_confidence: evidence,
    entry_zone_low: dominant.entry_zone_low, entry_zone_high: dominant.entry_zone_high,
    market_regime_region: region, combined_regime: combinedRegime,
    alternative_strategies_json: alternatives.map(a => ({ strategy: a.strategy, direction: a.direction, adjusted_score: a.adjustedScore })),
    fundamental_quality: fundTrend.quality, fundamental_momentum: fundTrend.momentum,
    valuation_context: fundTrend.valuation, fundamental_data_quality: fundTrend.dataQuality,
    news_catalyst_json: hatNews ? { richtung: newsRichtungByTicker[ticker], titel: newsGrundByTicker[ticker] } : null,
    configuration_snapshot_json: { regime_matrix_version: REGIME_MATRIX_VERSION, risk_model_version: RISK_MODEL_VERSION, thesis_rule_version: THESIS_RULE_VERSION, risk_cfg: RISK_CFG },
    // Welle 1, AP6
    risk_amount: risk ? risk.riskAmount : null, unit_risk: risk ? risk.unitRisk : null,
    theoretical_quantity: risk ? risk.theoreticalQuantity : null, position_value: risk ? risk.positionValue : null,
    position_value_pct: risk ? risk.positionValuePct : null, reward_risk_ratio: risk ? risk.rewardRiskRatio : null,
    estimated_fees: risk ? risk.estimatedFees : null, estimated_slippage: risk ? risk.estimatedSlippage : null,
    max_planned_loss: risk ? risk.maxPlannedLoss : null, risk_model_version: RISK_MODEL_VERSION,
    // Welle 1, AP7
    strategy: thesis.strategy, trade_thesis: thesis.tradeThesis, thesis_created_at: thesis.thesisCreatedAt,
    thesis_expires_at: thesis.thesisExpiresAt, expected_holding_days: thesis.expectedHorizonDays,
    time_stop_at: thesis.timeStopAt, invalidation_conditions_json: thesis.invalidationConditions, thesis_rule_version: thesis.ruleVersion
  }});
}
function qi_dataQuality(ticker) { return qualityInfo(ticker).dataQualityStatus; }

// Bestehende offene Positionen indexieren
const offenByTicker = {};
for (const row of empfehlungRows) if (row.status === 'offen' && row.ticker) offenByTicker[String(row.ticker).trim()] = row;

// ------------------------------------------------------------
// Hauptschleife: JEDER Ticker mit heutigem Preissignal wird bewertet
// (Welle 2: nicht mehr nur News+Technik-Kombos wie vor Welle 2).
// ------------------------------------------------------------
for (const ticker of Object.keys(signalByTicker)) {
  const evalResult = evaluateTickerStrategies(ticker);
  if (!evalResult || !evalResult.dominant) continue;
  const { dominant, signal } = evalResult;
  const richtung = dominant.direction === 'long' ? 'kauf' : 'verkauf';
  const offen = offenByTicker[ticker];

  if (!offen) {
    buildOpenCandidate(ticker, evalResult);
    continue;
  }
  if (offen.richtung === richtung) continue; // gleiche Richtung -> keine Aktion, Position bleibt offen

  // Gegensignal: Schliessen (mit Welle-1-Datenqualitaets-Fallback, NIE blockiert)
  const kursWertHeute = Number(signal.aktueller_kurs);
  const kursHeuteUngueltig = signal.aktueller_kurs === null || signal.aktueller_kurs === undefined || signal.aktueller_kurs === '' || isNaN(kursWertHeute) || kursWertHeute <= 0;
  let exitKursWert = kursWertHeute;
  let exitDatenqualitaetHinweis = null;
  if (kursHeuteUngueltig) {
    const fallback = letzterGueltigerKurs(ticker);
    if (fallback) { exitKursWert = fallback.kurs; exitDatenqualitaetHinweis = `Heutiger Kurs ungueltig - Schliessung mit letztem bekannten gueltigen Kurs vom ${fallback.datum}.`; }
    else exitDatenqualitaetHinweis = 'Kein verwertbarer Kurs vorhanden - Schliessung ohne Performance-Berechnung, manuelle Pruefung empfohlen.';
  }
  const entryKurs = Number(offen.entry_kurs);
  let performancePct = null;
  if (!isNaN(entryKurs) && exitKursWert !== null && !isNaN(exitKursWert) && entryKurs > 0) {
    performancePct = offen.richtung === 'kauf' ? ((exitKursWert - entryKurs) / entryKurs) * 100 : ((entryKurs - exitKursWert) / entryKurs) * 100;
    performancePct = parseFloat(performancePct.toFixed(2));
  }
  output.push({ json: {
    _aktion: 'schliessen', run_id, _dry_run: DRY_RUN, _require_confirmation: REQUIRE_CONFIRMATION,
    ticker, _existing_id: offen.id, exit_datum: heute, exit_kurs: exitKursWert,
    exit_grund: `[SIMULATION] Gegensignal (Strategie ${dominant.strategy})` + (exitDatenqualitaetHinweis ? ' | ' + exitDatenqualitaetHinweis : ''),
    performance_pct: performancePct, letzte_aktualisierung: zeitstempel
  }});

  if (!kursHeuteUngueltig) buildOpenCandidate(ticker, evalResult);
  else console.warn(`[Welle 2] ${ticker}: Neueroeffnung nach Schliessung uebersprungen (kein gueltiger heutiger Kurs).`);
}

