const requireConfirmation = cfgByKey.hasOwnProperty('REQUIRE_CONFIRMATION') ? cfgByKey.REQUIRE_CONFIRMATION : true;
// FIX 2026-08-01 (Fehleranalyse B4, kritisch): Fallback sprang bei fehlendem DRY_RUN-Config-
