// Garant-Trigger: n8n ueberspringt einen Node komplett, wenn ALLE seine
// Eingaenge 0 Items liefern (nicht nur leere Ausgabe, sondern gar keine
// Ausfuehrung) -- an einem Tag ganz ohne Kandidaten (leere Watchlist, kein
// DRY_RUN) laufen dadurch IF: DRY_RUN aktiv? und alles danach ueberhaupt
// nicht, live beobachtet als {} Rueckgabe an 00 trotz vorherigem Merge-Fix.
// Dieser Node haengt direkt an Trigger-Eingabe normalisieren (garantiert
// genau 1 Item, unabhaengig von jeder Kandidatenzahl) und stellt sicher,
// dass der finale Merge immer mindestens einen abgeschlossenen Eingang hat.
return [{ json: { _guard: true } }];

// Prioritaet 6: einheitliches Envelope. Genau EIN Zweig liefert pro Lauf
// tatsaechlich Items (DRY_RUN vs. echter Schreibpfad schliessen sich vor
// diesem Merge gegenseitig aus, siehe IF: DRY_RUN aktiv?), daher reicht eine
// Formerkennung am Item-Inhalt statt an der Merge-Eingangsseite.
// Der echte Pfad enthaelt zusaetzlich die Matrix-Sende-Antwort (kein
// _aktion-Feld, sonst haette die urspruengliche Matrix-Nachricht keinen
// Rueckgabewert und der Execute-Workflow-Aufruf aus 00 laeuft ins Leere,
// live beobachtet: 06 lieferte {} statt Envelope zurueck) -- die wird vor
// der Zaehlung explizit herausgefiltert, analog zum ticker!==undefined-
// Filter in 02s Abschluss-Ergebnis bauen. Das Guard-Trigger-Item (kein
// _aktion, kein dry_run) wird ebenso herausgefiltert -- es dient nur dazu,
// den vorgelagerten Merge an Tagen ganz ohne Kandidaten ueberhaupt zum
// Feuern zu bringen (siehe Envelope: Guard-Trigger).
const rawItems = $input.all().map(i => i.json);
const items = rawItems.filter(i => i._guard !== true);

let runId = null, startedAt = null;
try {
  const t = $('Trigger-Eingabe normalisieren').all()[0].json;
  runId = t.run_id;
  startedAt = t._run_started_at || null;
} catch (e) {}

const isDryRun = items.length > 0 && items.every(i => i.dry_run === true);

let processed, successful, failed, warnings, errors, status;

if (isDryRun) {
  const planned = (items[0] && items[0].planned_actions) || [];
  processed = planned.length;
  successful = 0;
  failed = 0;
  warnings = [];
  errors = [];
  status = 'skipped';
} else {
  const relevant = items.filter(i => i._aktion !== undefined);
  processed = relevant.length;
  const failedItems = relevant.filter(i => i._write_failed === true);
  const proposalItems = relevant.filter(i => i._aktion === 'vorschlag_ungespeichert');
  failed = failedItems.length;
  successful = processed - failed - proposalItems.length;
  warnings = proposalItems.map(i => ({ ticker: i.ticker || null, message: 'Vorschlag ohne Schreibvorgang (' + (i._confirmation_reason || 'REQUIRE_CONFIRMATION aktiv') + ')' }));
  errors = failedItems.map(i => ({
    ticker: i.ticker || i._existing_id || null,
    node: i._aktion === 'oeffnen' ? 'DB: Empfehlung \u00f6ffnen' : 'DB: Empfehlung schlie\u00dfen',
    message: i._write_error || 'Unbekannter Fehler'
  }));
  if (processed === 0) status = 'skipped';
  else if (failed === 0) status = 'success';
  else if (successful === 0 && proposalItems.length === 0) status = 'failed';
  else status = 'partial_failure';
}

return [{ json: {
  ok: failed === 0,
  workflow: '06 \u2013 Empfehlungswatchlist',
  run_id: runId,
  processed,
  successful,
  failed,
  warnings,
  errors,
  started_at: startedAt,
  finished_at: new Date().toISOString(),
  status
} }];

return $input.all().map((i, idx) => {
  const j = i.json;
  const failed = !!j.error || j.id === undefined || j.id === null;
  const errMsg = String(j.message || (j.error && j.error.description) || 'Unbekannter Fehler beim Schreiben (kein id in RETURNING)');
  if (failed) {
    const original = $('Oeffnen: SQL bauen').all()[idx];
    const base = (original && original.json) || {};
    return { json: { ...base, _aktion: 'oeffnen', _write_failed: true, _write_error: errMsg } };
  }
  return { json: { ...j, _aktion: 'oeffnen', _write_failed: false, _write_error: null } };
});

return $input.all().map((i, idx) => {
  const j = i.json;
  const failed = !!j.error || j.id === undefined || j.id === null;
  const errMsg = String(j.message || (j.error && j.error.description) || 'Unbekannter Fehler beim Schreiben (kein id in RETURNING)');
  if (failed) {
    const original = $('Schliessen: SQL bauen').all()[idx];
    const base = (original && original.json) || {};
