  return { json: { ...j, _aktion: 'schliessen', _write_failed: false, _write_error: null } };
});

function pgStr(v) { return v === null || v === undefined || v === '' ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { if (v === true) return 'TRUE'; if (v === false) return 'FALSE'; return 'NULL'; }
function pgJson(v) { return (v === null || v === undefined) ? "'[]'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }
function pgJsonObj(v) { return (v === null || v === undefined) ? "'{}'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

